INSERT INTO `nivel` (`id`, `nome`, `slug`, `apresentacao`, `ativo`) VALUES
(1, 'Graduação', 'graduacao', '', '1'),
(2, 'Pós Graduação', 'pos-graduacao', '<p><strong>Diferenciais da Pós Graduação IESB</strong></p><p><br>Aproveitamento de Disciplinas&nbsp;<br>Disciplinas equivalentes cursadas em outras Instituições de Ensino, no mesmo nível de Pós-Graduação, poderão ser aproveitadas mediante análise da coordenação acadêmica.&nbsp;<br>(*<i>) O aproveitamento não gera redução de valores no curso de Pós-Graduação, exceto para disciplinas realizadas em cursos que foram realizados&nbsp; sob coordenação da Profª Magda Brazil, conforme critérios institucionais.<strong>&nbsp;</strong></i></p><p>&nbsp;</p><p><strong>Flexibilidade nas Aulas&nbsp;</strong></p><ul><li>As aulas serão realizadas online e ao vivo, proporcionando interação em tempo real.&nbsp;</li><li>Todas as aulas serão gravadas e disponibilizadas para acesso posterior, permitindo maior flexibilidade de estudos conforme a disponibilidade do aluno.&nbsp;</li><li>Acesso às gravações permanecerá disponível por até 1 ano após a matrícula ou conclusão da primeira disciplina cursada&nbsp;</li></ul><p>&nbsp;</p><p>Educação Profissional Continuada- Capacitadora credenciada junto ao sistema CRC/CFC</p><p>As disciplinas dos cursos de Pós Graduação serão cadastradas junto ao gestor CRCRS para pontuação educação profissional continuada dos profissionais: contadores, auditores e peritos.</p>', '1'),
(3, 'Cursos Livres', 'cursos-livres', '<p>A IESB oferece cursos nas modalidades EAD e presencial, proporcionando flexibilidade, praticidade e uma experiência de aprendizado alinhada às necessidades dos alunos e do mercado profissional.<br>&nbsp;</p><p>Cursos livres com&nbsp; pontuação EPC- Educação Profissional Continuada mediante análise e aprovação do Gestor CRCRS</p><p>Os cursos EAD são realizados por meio da plataforma Google Meet, com aulas ao vivo, interação em tempo real e conteúdo atualizado. Todas as aulas são gravadas e disponibilizadas posteriormente, permitindo que o aluno acompanhe os estudos conforme sua disponibilidade de horário.</p><p>&nbsp;</p>', '1'),
(4, 'técnico', 'tecnico', '', '0');
